from rich.prompt import Prompt, InvalidResponse

console = Console(markup=False)
prompt = Prompt("Enter something", console=console)

def process_response(response):
    if response == "bad":
        raise InvalidResponse("[red]Error![/red] Invalid response")
    return response

# We need to subclass Prompt to override process_response
class MyPrompt(Prompt):
    def process_response(self, response):
        if response == "bad":
            raise InvalidResponse("[red]Error![/red] Invalid response")
        return super().process_response(response)

